Definition optmv_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A R lo : Z) (padA padR : list byte) (vr : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + 16)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' A (OptU64Cells true padA vr)
    /\ rw_cells bsegs m' R (OptU64Cells true padR vr)
    /\ ACONST m' /\ aobj m' A 16 /\ aobj m' R 16.

Definition optmv_stmt : Prop :=
  forall (A R lo : Z) (padA padR : list byte) (va vr : word)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m A (OptU64Cells false padA va) ->
  rw_cells bsegs m R (OptU64Cells true padR vr) ->
  (A + 16 <= R \/ R + 16 <= A) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + OPTMV_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= A \/ A + 16 <= lo) -> (bv_unsigned sp <= R \/ R + 16 <= lo) ->
  mem_inv bsegs m -> bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  ACONST m -> aobj m A 16 -> aobj m R 16 -> A mod 8 = 0 -> R mod 8 = 0 ->
  evt bsegs (optmv_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A R lo padA padR vr m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) (wz R) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_OPT_MOVE) fc None m (seg_rom bsegs)).

